function getMaterialStockEntry(material: RecordItem, movements: StockMovement[]) { const name = String(material.name || ""); const code = String(material.code || ""); const linkedMovements = movements.filter((movement) => movementMatchesMaterial(movement, material)).sort((a, b) => b.date.localeCompare(a.date)); const balance = materialBalance(material, movements); const minimum = numericQuantity(String(material.min ?? "")); const derivedStatus = balance <= 0 ? "Sem saldo" : minimum > 0 && balance < minimum ? "Abaixo do mínimo" : String(material.status || "Disponível"); return { material, name, code, linkedMovements, balance, minimum, derivedStatus, lastMovement: linkedMovements[0], location: String(material.location || "Almoxarifado") }; }
